#include <iostream>

int main() {
    unsigned int passes{0};
    unsigned int failures{0};
    unsigned int studentCounter{1};

    while (studentCounter <= 10) {
        std::cout << "Enter result (1 = pass, 2 = fail): ";
        int result{0};
        if (std::cin >> result) {
            if (result == 1) {
                passes = passes + 1;
            } else {
                failures = failures + 1;
            }
            studentCounter = studentCounter + 1;
        } else {
            break;
        }
    }

    std::cout << "Passed " << passes << "\nFailed " << failures << std::endl;

    if (passes > 8) {
        std::cout << "Bonus to instructor!" << std::endl;
    }

    return 0;
}

#include <iostream>

int main() {
    // List initialization (C++11/C++17)
    int total{0};
    int bonusPoints{5};

    // Compound assignment operator
    total += bonusPoints; // Equivalent to total = total + bonusPoints;
    total += 10;          // Equivalent to total = total + 10;

    std::cout << "Total score: " << total << std::endl;
    return 0;
}
